item):?><option value="<?=$item['id']?>" <?=$item['id']==$entry['department_id']?'selected':''?>><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Position<select name="position_id"><?php foreach($data['positions'] as $item):?><option value="<?=$item['id']?>" <?=$item['id']==$entry['position_id']?'selected':''?>><?=esc($item['name'])?></option><?php endforeach;?></select></label><label>Starts<input type="time" name="starts_at" value="<?=esc(substr($entry['starts_at'],0,5))?>"></label><label>Ends<input type="time" name="ends_at" value="<?=esc(substr($entry['ends_at'],0,5))?>"></label><label>Note<input name="notes" value="<?=esc($entry['notes']??'')?>"></label><button class="button primary">Save</button></form><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="deactivate_master_entry"><input type="hidden" name="master_schedule_id" value="<?=$selectedMasterId?>"><input type="hidden" name="entry_id" value="<?=$entry['id']?>"><button class="button secondary">Archive</button></form></details><?php endforeach;?></article>
