<article class="panel"><h2>Holiday and closure rule</h2><form method="post" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="add_schedule_exception"><input type="hidden" name="master_schedule_id" value="<?=$selectedMasterId?>"><label>Date<input type="date" name="exception_date" required></label><label>Name<input name="name" placeholder="Holiday or closure" required></label><label>Rule<select name="exception_type"><option value="closed">Closed</option><option value="special_hours">Special hours</option><option value="alternate_master">Alternate master</option></select></label><label>Opening<input type="time" name="starts_at"></label><label>Closing<input type="time" name="ends_at"></label><label>Alternate<select name="alternate_master_schedule_id"><option value="">Choose if applicable</option><?php foreach($masterSchedules as $master):?><option value="<?=$master['id']?>"><?=esc($master['name'])?></option><?php endforeach;?></select></label><button class="button primary">Save rule</button></form><?php foreach($scheduleExceptions as $exception):?><div class="planning-row"><span><strong><?=esc($exception['exception_date'].' · '.$exception['name'])?></strong><small><?=esc(ucwords(str_replace('_',' ',$exception['exception_type'])))?></small></span></div><?php endforeach;?></article>
<article class="panel span-2"><h2>Generated weeks</h2><?php foreach($masterGenerations as $generation):?><a class="planning-row" href="<?=esc(url_for('master-schedule?master_id='.$selectedMasterId.'&generation_id='.$generation['id']))?>"><span><strong>Week of <?=esc(date('M j, Y',strtotime($generation['week_starts_on'])))?></strong><small><?=$generation['shift_count']?> shifts · <?=$generation['conflict_count']?> exceptions</small></span><b class="state-pill <?=$generation['publication_status']==='published'?'covered':'gap'?>"><?=esc(ucfirst($generation['publication_status']))?></b></a><?php endforeach;?></article>
