tate-pill <?=$item['result']==='created'?'covered':'gap'?>"><?=esc(ucwords(str_replace('_',' ',$item['resolution']?:$item['result'])))?></b><?php endif;?></div><?php endforeach;?></article><?php endif;?><?php endif;?></section></main></body></html>
